    points = {}
    for r in range(h):
        for c in range(w):
            if out[r][c] in (1, 2, 3, 6):
                points.setdefault(out[r][c], []).append((r, c))

    def put(r, c, color):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = color

    # Each marker projects a fixed-length colored ray.
    for color, cells in points.items():
        for r, c in cells:
            if color == 1:
                put(r, c + 1, 5)
                put(r, c + 2, 5)
                put(r - 1, c + 2, 1)
            elif color == 2:
                for x in range(c - 1, c - 4, -1):
                    put(r, x, 5)
                put(r, c - 4, 2)
            elif color == 3:
                for y in range(r + 1, r + 3):
                    put(y, c, 5)
                put(r + 3, c, 3)
            elif color == 6:
                for y in range(r - 1, r - 6, -1):
                    put(y, c, 5)
                put(r - 6, c, 6)

    # A horizontal 2-ray crossing a vertical 3/6-ray makes the diagonal 4-ray.
    twos = points.get(2, [])
    verticals = points.get(3, []) + points.get(6, [])
    for r, c in twos:
        for vr, vc in verticals:
            if c - 4 <= vc <= c and (r <= vr + 3 if (vr, vc) in points.get(3, []) else vr - 6 <= r <= vr):
